<template><section class="section bg-neutral-950 text-white"><div class="container-page"><div class="flex items-end justify-between"><div><p class="text-sm font-semibold uppercase tracking-wider text-primary-300">Gallery</p><h2 class="mt-2 text-3xl">Explore the property</h2></div><p class="hidden text-sm text-neutral-400 sm:block">Scroll to view more →</p></div><div class="mt-7 flex snap-x snap-mandatory gap-4 overflow-x-auto pb-4"><figure v-for="item in sorted" :key="item.id" class="w-[88%] shrink-0 snap-center overflow-hidden rounded-2xl bg-black sm:w-[68%] lg:w-[48%]"><video v-if="isVideo(item)" :src="item.image_url" class="aspect-video w-full object-contain" controls playsinline preload="metadata"/><NuxtImg v-else :src="item.image_url" :alt="item.alt_text||propertyName" class="aspect-video w-full object-cover" loading="lazy"/><figcaption class="px-4 py-3 text-sm text-neutral-300">{{item.alt_text||propertyName}}</figcaption></figure></div></div></section></template>
<script setup lang="ts">import type{PropertyImage}from'~/types/database';const props=defineProps<{items:PropertyImage[];propertyName:string}>();const sorted=computed(()=>[...props.items].sort((a,b)=>Number(b.is_primary)-Number(a.is_primary)||a.sort_order-b.sort_order));const isVideo=(item:PropertyImage)=>item.media_type==='marketing_video'||/\.(mp4|webm|mov)(\?|$)/i.test(item.image_url)</script>
